mapper.select:
SELECT COALESCE(SUM(amount),0) FROM biz_order
WHERE customer_id = #{customerId} AND status IN ('PAID','INSTALLING','DONE')
  AND created_time >= #{start} AND created_time < #{end}

SELECT id, package_name AS packageName, amount, order_type AS orderType,
       status, created_time AS createdTime
FROM biz_order WHERE customer_id = #{customerId}

    AND DATE_FORMAT(FROM_UNIXTIME(created_time/1000), '%Y-%m') = #{period}

ORDER BY created_time DESC
